/* widget.min.js — TEST STUB ONLY.
 * The production artifact is produced by the esbuild Docker build stage
 * (node:20-slim + esbuild) which minifies frontend/widget.js.
 * This stub preserves the public API surface (PubotWidget global +
 * attachShadow) so route tests can verify response body contracts locally
 * without running Node/esbuild.
 * Obfuscation note: minification provides size reduction and mild deterrence,
 * NOT a security control. The real secret (csrf_secret) is never in JS.
 */
window.PubotWidget={mount:function(o){var h=o&&o.shadowRoot||document.body;h.attachShadow&&h.attachShadow({mode:"open"});}};
